values ((select id from public.programas where anio = 2027), 'entrada', 'Encuesta de entrada 2027', '{"version": 1, "escalas": {"acuerdo5": [[1, "Muy en desacuerdo"], [2, "En desacuerdo"], [3, "Ni de acuerdo ni en desacuerdo"], [4, "De acuerdo"], [5, "Muy de acuerdo"]], "interes5": [[1, "Nada interesado/a"], [2, "Poco interesado/a"], [3, "Ni interesado ni desinteresado"], [4, "Interesado/a"], [5, "Muy interesado/a"]], "sino4": [["si", "Sí"], ["tv", "Tal vez"], ["no", "No"], ["ns", "No sé"]], "conf5": [[1, "Nada de confianza"], [2, "Poca confianza"], [3, "Bastante confianza"], [4, "Mucha confianza"], ["ns", "No sé"]], "regimen": [[0, "La democracia es preferible a cualquier otra forma de gobierno"], [1, "En algunas circunstancias, un gobierno autoritario puede ser preferible a uno democrático"], [2, "A la gente como uno, le da lo mismo un régimen democrático que uno autoritario"]], "satisf4": [[1, "Muy satisfecho"], [2, "Satisfecho"], [3, "No muy satisfecho"], [4, "Nada satisfecho"]], "futuro4": [[1, "Mejor que ahora"], [2, "Igual que ahora"], [3, "Peor que ahora"], ["ns", "No sé"]], "nota5": [[1, "1 · Muy malo"], [2, "2"], [3, "3"], [4, "4"], [5, "5 · Muy bueno"]], "volver": [["si", "Sí"], ["tv", "Tal vez"], ["no", "No"]]}, "secciones": [{"id": "q1", "texto": "Respecto de tu conocimiento sobre los asuntos públicos, ¿qué tan de acuerdo estás con las siguientes afirmaciones?", "escala": "acuerdo5", "items": [{"id": "q1_1", "texto": "La política es tan complicada que una persona como yo no puede realmente entender qué está pasando.", "invertida": true}, {"id": "q1_2", "texto": "En términos generales, no me parece tan difícil tomar una posición sobre cuestiones políticas."}, {"id": "q1_3", "texto": "Cuando los políticos debaten sobre economía, sólo entiendo una pequeña parte de lo que dicen.", "invertida": true}, {"id": "q1_4", "texto": "Gente como yo está calificada como para participar en discusiones políticas."}, {"id": "q1_5", "texto": "Gente como yo tiene opiniones políticas que valen la pena ser escuchadas."}]}, {"id": "q2", "texto": "Respecto al sistema político e institucional actual, ¿qué tan de acuerdo estás con las siguientes afirmaciones?", "escala": "acuerdo5", "items": [{"id": "q2_1", "texto": "A los políticos no les interesa realmente qué es lo que los ciudadanos piensan.", "invertida": true}, {"id": "q2_2", "texto": "Usualmente puedes confiar en que los líderes políticos hacen lo mejor para el país."}, {"id": "q2_3", "texto": "Los políticos desperdician mucho dinero de los impuestos.", "invertida": true}, {"id": "q2_4", "texto": "Gente como yo no tiene influencia en lo que se decida en el congreso o en el gobierno.", "invertida": true}]}, {"id": "q3", "texto": "¿Qué tan interesado/a estás en la política?", "escala": "interes5", "items": [{"id": "q3", "texto": ""}]}, {"id": "q4", "texto": "En tu caso…", "escala": "sino4", "items": [{"id": "q4_1", "texto": "¿Tienes interés en formar parte de un partido político?"}, {"id": "q4_2", "texto": "¿Consideras que las votaciones son factor de cambio en la sociedad?"}, {"id": "q4_3", "texto": "¿Conversas de política con familiares, amistades u otras personas?"}, {"id": "q4_4", "texto": "¿Participarías de organizaciones o grupos que defienden alguna causa social? (medio ambiente, derechos de las mujeres, derechos humanos, derechos migrantes, etc.)"}]}, {"id": "q5", "texto": "¿Con cuál de las siguientes frases estás más de acuerdo?", "escala": "regimen", "items": [{"id": "q5", "texto": ""}]}, {"id": "q6", "texto": "En general, ¿qué tan satisfecho estás con el funcionamiento de la democracia en Chile?", "escala": "satisf4", "items": [{"id": "q6", "texto": ""}]}, {"id": "q7", "texto": "En términos generales, ¿cómo crees que vas a estar tú en 5 años más?", "escala": "futuro4", "items": [{"id": "q7", "texto": ""}]}, {"id": "q8", "texto": "¿Y cómo crees que va a estar Chile en 5 años más?", "escala": "futuro4", "items": [{"id": "q8", "texto": ""}]}, {"id": "q9", "texto": "¿Cuánta confianza tienes en las siguientes instituciones?", "escala": "conf5", "items": [{"id": "q9_1", "texto": "Congreso Nacional"}, {"id": "q9_2", "texto": "Tribunales de justicia"}, {"id": "q9_3", "texto": "Fuerzas Armadas"}, {"id": "q9_4", "texto": "PDI"}, {"id": "q9_5", "texto": "Carabineros"}, {"id": "q9_6", "texto": "Municipalidad"}, {"id": "q9_7", "texto": "Iglesias"}, {"id": "q9_8", "texto": "Junta de vecinos"}, {"id": "q9_9", "texto": "Bomberos"}, {"id": "q9_10", "texto": "Medios de comunicación"}, {"id": "q9_11", "texto": "Fundaciones"}, {"id": "q9_12", "texto": "Empresas privadas"}]}, {"id": "q10", "texto": "¿Qué tan de acuerdo o en desacuerdo estás con las siguientes afirmaciones sobre las redes sociales?", "escala": "acuerdo5", "items": [{"id": "q10_1", "texto": "Las redes sociales son una mejor herramienta que el voto para dar a conocer las demandas de la gente."}, {"id": "q10_2", "texto": "Las redes sociales me permiten incidir en forma directa en la toma de decisiones del Estado."}]}]}'::jsonb, false);

